147|        ) : (
148|          <Player
149|            track={track}
150|            fadeSec={fadeSec}
151|            sceneTitle={sceneTitle}
152|            canSkip={canSkip}
153|            onSkip={skip}
154|            onEnded={ended}
155|          />
156|        )}
157|      </div>
158|      {children}
159|    </>
160|  );
