+  const inStyle = manifest.soundtracks.filter(
+    (s) => s.style === style && scoped.some((t) => t.soundtrack === s.id),
+  );
+  let soundtrackId = inStyle[0]?.id ?? scoped[0]?.soundtrack ?? "";
